USE [JamunaBankProcurement];
GO
IF TYPE_ID(N'dbo.RequisitionItemTableType') IS NULL
 EXEC(N'CREATE TYPE dbo.RequisitionItemTableType AS TABLE(CLIENT_ITEM_KEY INT NOT NULL PRIMARY KEY,ASSET_ID BIGINT NOT NULL,REQ_TYPE VARCHAR(20) NOT NULL,QUANTITY DECIMAL(18,2) NOT NULL,ESTIMATED_UNIT_PRICE DECIMAL(18,2) NOT NULL,PURPOSE_JUSTIFICATION NVARCHAR(2000) NOT NULL,ADDITIONAL_SPEC_REQUIREMENT NVARCHAR(2000) NULL,ASSET_TAG_NO NVARCHAR(100) NULL,SERIAL_NO NVARCHAR(100) NULL,CURRENT_CONDITION NVARCHAR(2000) NULL,REPLACEMENT_ADDITIONAL_INFO NVARCHAR(2000) NULL);');
GO
IF TYPE_ID(N'dbo.RequisitionSpecValueTableType') IS NULL
 EXEC(N'CREATE TYPE dbo.RequisitionSpecValueTableType AS TABLE(CLIENT_ITEM_KEY INT NOT NULL,ASSET_SPEC_ID BIGINT NOT NULL,SPEC_TEXT_VALUE NVARCHAR(1000) NULL,SPEC_NUM_VALUE DECIMAL(18,4) NULL,SPEC_DATE_VALUE DATE NULL,SPEC_BOOL_VALUE BIT NULL,PRIMARY KEY(CLIENT_ITEM_KEY,ASSET_SPEC_ID));');
GO
IF TYPE_ID(N'dbo.RequisitionSpecOptionTableType') IS NULL
 EXEC(N'CREATE TYPE dbo.RequisitionSpecOptionTableType AS TABLE(CLIENT_ITEM_KEY INT NOT NULL,ASSET_SPEC_ID BIGINT NOT NULL,ASSET_SPEC_OPTION_ID BIGINT NOT NULL,PRIMARY KEY(CLIENT_ITEM_KEY,ASSET_SPEC_ID,ASSET_SPEC_OPTION_ID));');
GO
